source = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    row_score = max(sum(v == 2 for v in row) for row in grid)
    col_score = max(sum(grid[r][c] == 2 for r in range(h)) for c in range(w))
    # A dense horizontal 2-line sends rays vertically; a dense vertical line sends them horizontally.
    ray_vertical = row_score >= col_score

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    for r, c in centers:
        ray = [(rr, c) for rr in range(h)] if ray_vertical else [(r, cc) for cc in range(w)]
        for rr, cc in ray:
            if out[rr][cc] == 0:
                out[rr][cc] = 1
            if grid[rr][cc] == 2:
                # Each crossing of the ray and a 2-line gets a 3x3 perimeter.
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if abs(dr) + abs(dc) == 0:
                            continue
                        ar, ac = rr + dr, cc + dc
                        if 0 <= ar < h and 0 <= ac < w and out[ar][ac] == 0:
                            out[ar][ac] = 1
    return out
'''
